    private int aiJumpCooldown = 0;
    private int aiSpecialCooldown = 0;
    private int aiStrafeTimer = 0;
    private int aiStrafeDir = 1;
    private int aiIdleFrames = 0;
    private int aiCommitFrames = 0;
    private int aiRetreatCooldown = 0;
    private int aiMicroPause = 0;
    private int aiDirectionLock = 0;
    private int aiLockedDir = 0;
    private int aiStrafeHoldFrames = 0;
    private int aiPowerCommitFrames = 0;
    private int aiDropCommitFrames = 0;
    private int aiDropCommitDir = 0;
    private int aiVoidRecoveryLockFrames = 0;
    private int aiTargetLockFrames = 0;
    private int aiLockedTargetIndex = -1;
    private double aiDropOriginY = Double.NaN;
    private double aiLastHealth = STARTING_HEALTH;

    private int dashCooldown = 0;
    private int dashTimer = 0;
    private int lastTapDir = 0;
    private long lastTapTick = Long.MIN_VALUE / 2; // sim-tick of last tap; sentinel = "no tap yet"

    private void aiControl() {
        if (aiJumpCooldown > 0) aiJumpCooldown--;
        if (aiSpecialCooldown > 0) aiSpecialCooldown--;
        if (aiStrafeTimer > 0) aiStrafeTimer--;
        if (aiCommitFrames > 0) aiCommitFrames--;
        if (aiRetreatCooldown > 0) aiRetreatCooldown--;
        if (aiMicroPause > 0) aiMicroPause--;
        if (aiDirectionLock > 0) aiDirectionLock--;
        if (aiStrafeHoldFrames > 0) aiStrafeHoldFrames--;
        if (aiPowerCommitFrames > 0) aiPowerCommitFrames--;
        if (aiDropCommitFrames > 0) aiDropCommitFrames--;
        if (aiVoidRecoveryLockFrames > 0) aiVoidRecoveryLockFrames--;
        if (aiTargetLockFrames > 0) aiTargetLockFrames--;

        clearAIInputs();

        int cpuLevel = game.getCpuLevel(playerIndex);
        double rawSkill = Math.clamp((cpuLevel - 1) / 8.0, 0.0, 1.0);
        double skill = Math.pow(rawSkill, 2.1);
        double error = Math.min(1.0, 1.05 - skill);
        double currentDurability = aiDurabilityHealth();
        if (cpuLevel <= 1) {
            skill = 0.0;
            error = 1.0;
            if (random.nextDouble() < 0.22) {
                aiLastHealth = currentDurability;
                return;
            }
        }

        Bird target = pickAITarget();
        PowerUp powerUp = pickBestAIPowerUp(target);
        boolean onGround = isOnGround();
        Platform standing = findCurrentSupportPlatform();

        if (target == null && powerUp == null) {
            resetAIDropCommit();
            applyAIVoidRecoveryInputs(onGround, standing);
            aiLastHealth = currentDurability;
            return;
        }

        double myCx = x + 40;
        double targetDist = target != null ? Math.hypot(target.x - x, target.y - y) : Double.MAX_VALUE;
        double idealRange = getAIIdealRange();
        boolean lowHealth = currentDurability < 38;
        boolean tookDamageRecently = currentDurability < aiLastHealth - 1.0;
        if (tookDamageRecently && target != null && targetDist < 300) {
            aiCommitFrames = Math.max(aiCommitFrames, 42 + random.nextInt(20));
        }
        if (cpuLevel > 1 && target != null && aiCommitFrames <= 0 && targetDist < 240 && random.nextDouble() < 0.012 * (0.4 + 0.6 * skill)) {
            aiCommitFrames = 36 + random.nextInt(26);
        }
        if (cpuLevel <= 1) {
            aiCommitFrames = 0;
        }

        // Emergency self-preservation before anything else.
        if (onGround && y > BirdGame3.GROUND_Y + 220) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            aiJumpCooldown = 12;
        }

        if (handleAIDodgeBurstThreats(target, onGround)) {
            aiLastHealth = currentDurability;
            return;
        }

        PowerUp healthPack = findBestHealthPowerUp();
        boolean veryLowHealth = currentDurability < 20;
        boolean losingHard = target != null && target.aiDurabilityHealth() > currentDurability + 32;
        boolean retreatWindow = aiRetreatCooldown <= 0 && (veryLowHealth || (currentDurability < 28 && losingHard));
        boolean shouldRetreat = target != null && retreatWindow && targetDist < 220 && healthPack == null && aiCommitFrames <= 0;
        boolean immediatePowerChance = isImmediatePowerUpOpportunity(powerUp);
        boolean shouldChasePower = powerUp != null &&
                ((shouldPrioritizePowerUp(powerUp, target) && aiCommitFrames <= 0) || immediatePowerChance);
        if (shouldChasePower) {
            aiPowerCommitFrames = Math.max(aiPowerCommitFrames, immediatePowerChance ? 44 : 30);
        }
        boolean powerFocus = powerUp != null && !shouldRetreat && (shouldChasePower || aiPowerCommitFrames > 0);
        if (powerFocus && !isPowerUpConvenient(powerUp, target)) {
            powerFocus = false;
            aiPowerCommitFrames = 0;
        }
        if (powerFocus && target != null && targetDist < idealRange * 0.85) {
            powerFocus = false;
            aiPowerCommitFrames = 0;
        }

        if (powerFocus) {
            // Keep movement deterministic while committing to a pickup.
            aiDirectionLock = 0;
            aiMicroPause = 0;
        }

        double dyToTarget = target != null ? target.y - y : 0;
        boolean targetBelow = target != null && dyToTarget > 160;
        boolean dropPlan = false;
        double dropEdgeX = x;
        if (targetBelow && onGround && standing != null && !isBoundaryPlatform(standing)) {
            double dropOffset = 60;
            double leftEdge = standing.x - dropOffset - 40 * sizeMultiplier;
            double rightEdge = standing.x + standing.w + dropOffset - 40 * sizeMultiplier;
            double platformCenter = standing.x + standing.w / 2.0;
            double targetCx = target.x + 40;
            double candidateDropEdgeX = targetCx < platformCenter ? leftEdge : rightEdge;
            if (isAIDropGoalSafe(candidateDropEdgeX, target.y + 40)) {
                dropEdgeX = candidateDropEdgeX;
                dropPlan = true;
                aiDropCommitDir = targetCx < platformCenter ? -1 : 1;
                aiDropCommitFrames = Math.max(aiDropCommitFrames, 24);
                aiDropOriginY = standing.y;
            }
        }
        boolean lowCpu = cpuLevel <= 2;
        double goalX;
        if (shouldRetreat) {
            goalX = x + (x - target.x) * 1.35;
            aiRetreatCooldown = 90 + random.nextInt(45);
        } else if (powerFocus) {
            goalX = pickPowerUpGoalX(powerUp);
        } else if (target != null) {
            // Predict movement instead of chasing current position.
            double lead = Math.clamp(targetDist / 120.0, 2.0, 10.0);
            if (lowCpu) lead *= 0.55;
            double predictedX = target.x + target.vx * lead;
            if (targetBelow) {
                goalX = dropPlan ? dropEdgeX : predictedX;
            } else if (targetDist > idealRange * 1.25) {
                goalX = predictedX;
            } else if (targetDist < idealRange * 0.65) {
                if (aiCommitFrames > 0) {
                    goalX = target.x + (random.nextBoolean() ? 1 : -1) * 65;
                } else {
                    goalX = target.x + (x < target.x ? -1 : 1) * 95;
                }
            } else {
                double desiredOffset = aiCommitFrames > 0 ? 95 : 125;
                double strafeTargetX = target.x + aiStrafeDir * desiredOffset;
                double strafeError = Math.abs(x - strafeTargetX);
                if (aiStrafeHoldFrames <= 0 && aiStrafeTimer <= 0 && strafeError < 55) {
                    aiStrafeDir *= -1;
                    aiStrafeHoldFrames = 26 + random.nextInt(24);
                    aiStrafeTimer = 18 + random.nextInt(18);
                } else if (aiStrafeHoldFrames <= 0 && aiStrafeTimer <= 0) {
                    aiStrafeHoldFrames = 18 + random.nextInt(18);
                    aiStrafeTimer = 14 + random.nextInt(14);
                }
                goalX = target.x + aiStrafeDir * desiredOffset;
            }
        } else {
            goalX = x;
        }

        Platform climbPlatform = null;
        boolean verticalPlan = false;
        if (!powerFocus && target != null) {
            if (dyToTarget < -160) {
                double maxRise = 520 + 180 * skill;
                climbPlatform = findClimbPlatform(target.x + 40, maxRise);
                if (climbPlatform != null) {
                    goalX = climbPlatform.x + climbPlatform.w / 2.0 - 40 * sizeMultiplier;
                    verticalPlan = true;
                }
            } else if (dyToTarget > 180 && onGround) {
                if (standing != null && !isBoundaryPlatform(standing)) {
                    goalX = (target.x < x) ? (standing.x - 20) : (standing.x + standing.w + 20);
                    verticalPlan = true;
                }
            }
        }

        if (!powerFocus && target != null && error > 0.0 && !dropPlan) {
            goalX += (random.nextDouble() - 0.5) * 160 * error;
        }

        goalX = Math.clamp(goalX, 120.0, BirdGame3.WORLD_WIDTH - 120.0);
        goalX = clampGoalXAwayFromVoid(goalX);
        boolean offstageCommit = aiGoalLeavesMainStage(goalX);

        if (powerFocus) facingRight = powerUp.x > myCx;
        else if (target != null) facingRight = target.x > myCx;
        else facingRight = powerUp.x > myCx;

        int moveDir = 0;
        if (dropPlan) {
            goalX = clampGoalXAwayFromVoid(dropEdgeX);
            offstageCommit = aiGoalLeavesMainStage(goalX);
            aiDirectionLock = 0;
            aiStrafeHoldFrames = 0;
            aiStrafeTimer = 0;
            aiMicroPause = 0;
        }
        double moveDeadZone = targetBelow ? 120 : 35;
        if (!dropPlan && Math.abs(goalX - x) > moveDeadZone) {
            moveDir = goalX < x ? -1 : 1;
        }
        if (!powerFocus && target != null) {
            double loiterChance = cpuLevel <= 1 ? 0.45 : (cpuLevel == 2 ? 0.25 : 0.0);
            if (loiterChance > 0 && random.nextDouble() < loiterChance) {
                moveDir = 0;
            }
        }
        if (dropPlan) {
            moveDir = goalX < x ? -1 : 1;
            aiDirectionLock = 0;
            aiStrafeHoldFrames = 0;
        }

        // Anti-stall fallback: if spacing logic leaves us idle too long, pressure target.
        if (!powerFocus && !dropPlan && target != null && moveDir == 0 && targetDist > 130 && cpuLevel > 2) {
            aiIdleFrames++;
            if (aiIdleFrames > 24) {
                moveDir = target.x < x ? -1 : 1;
            }
        } else {
            aiIdleFrames = 0;
        }

        if (!powerFocus && !verticalPlan && !dropPlan && !targetBelow && target != null && onGround && targetDist < 270 &&
                aiDirectionLock <= 0 && random.nextDouble() < 0.02 * (0.35 + 0.65 * skill)) {
            aiDirectionLock = 18 + random.nextInt(30);
            aiLockedDir = target.x < x ? -1 : 1;
        }
        if (!powerFocus && !verticalPlan && !dropPlan && !targetBelow && aiDirectionLock > 0) {
            moveDir = aiLockedDir;
        }

        if (!powerFocus && !verticalPlan && !dropPlan && !targetBelow && onGround && aiMicroPause <= 0 && target != null &&
                targetDist > 160 && random.nextDouble() < 0.008 + 0.02 * error) {
            aiMicroPause = 6 + random.nextInt(10 + (int) (error * 10));
        }
        if (!powerFocus && targetBelow && lowCpu && aiMicroPause <= 0 && random.nextDouble() < 0.12) {
            aiMicroPause = 12 + random.nextInt(18);
        }
        if (!powerFocus && !verticalPlan && !dropPlan && !targetBelow && aiMicroPause > 0 && targetDist > 150) {
            moveDir = 0;
        }

        if (aiDropCommitFrames > 0) {
            boolean abandonDrop = powerFocus || target == null || !targetBelow;
            boolean clearedDrop = !Double.isNaN(aiDropOriginY) && y > aiDropOriginY + 4;
            boolean landedLower = onGround && standing != null
                    && !Double.isNaN(aiDropOriginY)
                    && standing.y > aiDropOriginY + 12;
            if (abandonDrop || clearedDrop || landedLower) {
                resetAIDropCommit();
            } else if (aiDropCommitDir != 0) {
                moveDir = aiDropCommitDir;
                aiDirectionLock = 0;
                aiStrafeHoldFrames = 0;
                aiStrafeTimer = 0;
                aiMicroPause = 0;
            }
        }

        if (isVoidMap() && moveDir != 0) {
            double projectedX = x + moveDir * Math.max(18.0, type.speed * speedMultiplier * 4.0);
            if (Math.abs(clampGoalXAwayFromVoid(projectedX) - projectedX) > 0.1) {
                moveDir = 0;
            }
        }

        boolean voidRecovery = applyAIVoidRecoveryInputs(onGround, standing);
        if (!voidRecovery) {
            if (moveDir < 0) game.setAiControlKey(playerIndex, leftKey(), true);
            if (moveDir > 0) game.setAiControlKey(playerIndex, rightKey(), true);
        } else {
            aiLastHealth = currentDurability;
            return;
        }

        // Vertical positioning and recovery behavior.
        if (!powerFocus && target != null) {
            double dy = target.y - y;
            if (onGround && aiJumpCooldown <= 0) {
                double climbCenter = climbPlatform != null ? climbPlatform.x + climbPlatform.w / 2.0 : myCx;
                boolean alignedForClimb = !verticalPlan || climbPlatform == null || Math.abs((x + 40) - climbCenter) < 165;
                boolean jumpForHeight = dy < -120 && Math.abs(target.x - x) < 420 && alignedForClimb;
                boolean jumpForCombo = dy > 70 && targetDist < 220;
                boolean jumpForAboveClose = dy < -200 && Math.abs(target.x - x) < 220 && alignedForClimb;
                boolean jumpForOffstageLaunch = shouldAIJumpBeforeOffstage(goalX);
                double jumpSense = 0.35 + 0.65 * skill;
                if (jumpForOffstageLaunch) {
                    game.setAiControlKey(playerIndex, jumpKey(), true);
                    aiJumpCooldown = 14;
                } else if ((jumpForHeight || jumpForCombo || jumpForAboveClose) && random.nextDouble() < jumpSense) {
                    game.setAiControlKey(playerIndex, jumpKey(), true);
                    aiJumpCooldown = 14;
                }
                if (verticalPlan && climbPlatform != null) {
                    if (Math.abs((x + 40) - climbCenter) < 165 && dy < -140) {
                        game.setAiControlKey(playerIndex, jumpKey(), true);
                        aiJumpCooldown = 14;
                    }
                }
            }

            if (!onGround && currentFlyUpForce() > 0) {
                Platform mainStage = findAIMainStagePlatform();
                boolean recoverAltitude = y > BirdGame3.GROUND_Y - 120;
                boolean maintainVsTarget = target.y < y + 180 && !isAIAboveCruiseCeiling(target, mainStage);
                boolean recoverVoid = isVoidMap() && (offstageCommit || isAIVoidRecoveryUrgent(false, standing));
                if (recoverAltitude || maintainVsTarget || recoverVoid) {
                    game.setAiControlKey(playerIndex, jumpKey(), true);
                }
            }
        } else if (onGround && aiJumpCooldown <= 0 && powerUp.y < y - 120) {
            double dx = Math.abs(powerUp.x - (x + 40));
            double dy = (y + 40) - powerUp.y;
            if (dx < 140 && dy < 320) {
                game.setAiControlKey(playerIndex, jumpKey(), true);
                aiJumpCooldown = 14;
            }
        }

        if (shouldAIUseUtilitySpecial(target, powerUp, onGround, climbPlatform, powerFocus)) {
            if (type == BirdGame3.BirdType.PENGUIN) {
                game.setAiControlKey(playerIndex, jumpKey(), true);
            }
            game.setAiControlKey(playerIndex, specialKey(), true);
            aiSpecialCooldown = 18;
            aiLastHealth = currentDurability;
            return;
        }

        // Defensive block read (ground only).
        if (onGround && target != null && targetDist < 170 && target.attackAnimationTimer > 3 &&
                facingRight == (target.x > x) && random.nextDouble() < (lowHealth ? 0.50 : 0.34) * (0.25 + 0.75 * skill)) {
            game.setAiControlKey(playerIndex, blockKey(), true);
        }

        // Attack cadence respects role/range.
        double attackChance = (aiCommitFrames > 0 ? 0.96 : 0.84) * (0.45 + 0.55 * skill);
        if (cpuLevel <= 1) attackChance *= 0.04;
        else if (cpuLevel == 2) attackChance *= 0.35;
        if (!powerFocus && target != null && attackCooldown <= 0 &&
                targetDist < Math.max(140, idealRange * 0.95) &&
                Math.abs(target.y - y) < 115 &&
                random.nextDouble() < attackChance) {
            game.setAiControlKey(playerIndex, attackKey(), true);
        }

        // Special ability timing by bird role.
        if (!powerFocus && target != null
                && (isRaptor() ? canStartRaptorSpecial()
                : type == BirdGame3.BirdType.TURKEY ? canStartTurkeySpecial()
                : type == BirdGame3.BirdType.PENGUIN ? canStartPenguinSpecial()
                : type == BirdGame3.BirdType.SHOEBILL ? shoebillAnySpecialReady()
                : type == BirdGame3.BirdType.MOCKINGBIRD ? canStartMockingbirdSpecial()
                : type == BirdGame3.BirdType.RAZORBILL ? canStartRazorbillSpecial()
                : type == BirdGame3.BirdType.GRINCHHAWK ? canStartGrinchhawkSpecial()
                : type == BirdGame3.BirdType.VULTURE ? canStartVultureSpecial()
                : type == BirdGame3.BirdType.TITMOUSE ? canStartTitmouseSpecial()
                : type == BirdGame3.BirdType.BAT ? canStartBatSpecial()
                : type == BirdGame3.BirdType.RAVEN ? canStartRavenSpecial()
                : type == BirdGame3.BirdType.GOOSE ? canStartGooseSpecial()
                : isOpiumEchoPair() ? canStartOpiumSpecial()
                : specialCooldown <= 0)
                && aiSpecialCooldown <= 0 &&
                shouldUseSpecialAI(target, targetDist, onGround, lowHealth) &&
                random.nextDouble() < (0.25 + 0.75 * skill)) {
            if (type == BirdGame3.BirdType.PIGEON && onGround && lowHealth && targetDist > 110) {
                game.setAiControlKey(playerIndex, blockKey(), true);
            }
            if (type == BirdGame3.BirdType.SHOEBILL) {
                configureShoebillAISpecialInputs(target, targetDist, onGround);
            }
            if (type == BirdGame3.BirdType.RAZORBILL) {
                configureRazorbillAISpecialInputs(target, targetDist, onGround);
            }
            if (type == BirdGame3.BirdType.TITMOUSE) {
                configureTitmouseAISpecialInputs(target, targetDist, onGround);
            }
            if (type == BirdGame3.BirdType.BAT) {
                configureBatAISpecialInputs(target, targetDist, onGround);
            }
            if (type == BirdGame3.BirdType.RAVEN) {
                configureRavenAISpecialInputs(target, targetDist, onGround);
            }
            if (type == BirdGame3.BirdType.GOOSE) {
                configureGooseAISpecialInputs(target, targetDist, onGround);
            }
            if (isOpiumEchoPair()) {
                configureOpiumAISpecialInputs(target, targetDist, onGround);
            }
            game.setAiControlKey(playerIndex, specialKey(), true);
            aiSpecialCooldown = type == BirdGame3.BirdType.PIGEON ? 16
                    : (type == BirdGame3.BirdType.SHOEBILL
                    || type == BirdGame3.BirdType.RAZORBILL
                    || type == BirdGame3.BirdType.RAVEN
                    || type == BirdGame3.BirdType.GOOSE
                    || isOpiumEchoPair() ? 20 : 26);
        }

        if (!powerFocus && tauntCooldown <= 0 && target != null && currentDurability > 80
                && target.aiDurabilityHealth() < 35 &&
                targetDist < 200 && random.nextDouble() < 0.006) {
            currentTaunt = random.nextInt(3) + 1;
            tauntTimer = 50;
            tauntCooldown = 300;
            game.addToKillFeed(shortName() + " IS ABSOLUTELY COOKING!");
        }

        aiLastHealth = currentDurability;
    }

    void specialBatNeutral(boolean ultimate) {
        boolean boosted = consumeBatAmbushSpecialBonus();
        batNeutralReuseTimer = ultimate ? BAT_NEUTRAL_REUSE_FRAMES + 8 : BAT_NEUTRAL_REUSE_FRAMES;
        specialCooldown = 0;
        specialMaxCooldown = 0;
        double angle;
        if (batHanging) {
            angle = facingRight ? Math.toRadians(64.0) : Math.toRadians(116.0);
        } else if (!isOnGround()) {
            angle = facingRight ? Math.toRadians(12.0) : Math.toRadians(168.0);
        } else {
            angle = facingRight ? 0.0 : Math.PI;
        }
        emitBatEchoLance(angle,
                ultimate ? 11 : 8,
                ultimate ? 17 : 13,
                ultimate ? 12 : 8,
                ultimate ? 28 : 18,
                ultimate,
                boosted,
                true);
        game.addToKillFeed(shortName() + (ultimate ? " FIRED ULT ECHO LANCE!" : " FIRED ECHO LANCE!"));
    }

    void specialBatWingcut(boolean ultimate) {
        boolean fromHang = batHanging;
        if (fromHang) {
            releaseBatHang();
        }
        batWingcutTimer = ultimate ? BAT_WINGCUT_FRAMES + 4 : BAT_WINGCUT_FRAMES;
        batWingcutReuseTimer = ultimate ? BAT_WINGCUT_REUSE_FRAMES - 6 : BAT_WINGCUT_REUSE_FRAMES;
        batWingcutDirection = leftPressed() != rightPressed()
                ? (rightPressed() ? 1 : -1)
                : facingDirection();
        batWingcutUltimate = ultimate;
        batWingcutAmbush = consumeBatAmbushSpecialBonus();
        batWingcutFromHang = fromHang;
        Arrays.fill(batWingcutHit, false);
        facingRight = batWingcutDirection > 0;
        vx = batWingcutDirection * (fromHang ? (ultimate ? 20.0 : 17.0) : (ultimate ? 22.0 : 19.0));
        vy = fromHang ? 0.0 : (isOnGround() ? -8.0 : -6.0);
        specialCooldown = 0;
        specialMaxCooldown = 0;
        game.addToKillFeed(shortName() + (ultimate ? " CARVED AN ULT WINGCUT!" : " CARVED A WINGCUT!"));
    }

    void specialBatMoonrise(boolean ultimate) {
        if (batHanging) {
            releaseBatHang();
        }
        batMoonriseTimer = ultimate ? BAT_MOONRISE_FRAMES + 4 : BAT_MOONRISE_FRAMES;
        batMoonriseUsed = true;
        batMoonriseUltimate = ultimate;
        batMoonriseBurstResolved = false;
        batMoonriseAmbush = consumeBatAmbushSpecialBonus();
        Arrays.fill(batMoonriseHit, false);
        vx *= 0.38;
        vy = ultimate ? -24.0 : -21.0;
        canDoubleJump = false;
        specialCooldown = 0;
        specialMaxCooldown = 0;
        game.addToKillFeed(shortName() + (ultimate ? " ROSE IN ULT MOONRISE!" : " ROSE IN MOONRISE!"));
    }

    void specialBatSilentDescent(boolean ultimate) {
        boolean fromHang = batHanging;
        boolean fromGround = isOnGround();
        if (fromHang) {
            releaseBatHang();
        }
        batSilentStallTimer = fromHang ? 4 : BAT_SILENT_STALL_FRAMES
                + (fromGround ? BAT_SILENT_GROUND_RISE_FRAMES : 0);
        batSilentDiveTimer = 0;
        batSilentReuseTimer = ultimate ? BAT_SILENT_REUSE_FRAMES - 8 : BAT_SILENT_REUSE_FRAMES;
        batSilentFromHang = fromHang;
        batSilentUltimate = ultimate;
        batSilentAmbush = consumeBatAmbushSpecialBonus();
        Arrays.fill(batSilentHit, false);
        vx *= 0.24;
        vy = fromGround ? (ultimate ? -15.0 : -13.0) : Math.min(vy, 0.0);
        specialCooldown = 0;
        specialMaxCooldown = 0;
        game.addToKillFeed(shortName() + (ultimate ? " VANISHED INTO ULT SILENT DESCENT!" : " VANISHED INTO SILENT DESCENT!"));
    }

    void specialBatCathedralEcho() {
        if (batHanging) {
            releaseBatHang();
            vy = Math.min(vy, -12.0);
        }
        boolean boosted = consumeBatAmbushSpecialBonus();
        batCathedralTimer = BAT_CATHEDRAL_FRAMES;
        batCathedralPulseCooldown = 0;
        batCathedralWaveIndex = 0;
        specialCooldown = 0;
        specialMaxCooldown = 0;
        game.shakeIntensity = Math.max(game.shakeIntensity, 24);
        game.hitstopFrames = Math.max(game.hitstopFrames, 12);
        applyBatCathedralInitialBurst(boosted);
        fireBatCathedralPulse();
        game.addToKillFeed(shortName() + " OPENED CATHEDRAL ECHO!");
    }

    private boolean consumeBatAmbushSpecialBonus() {
        if (type != BirdGame3.BirdType.BAT || batAmbushWindowTimer <= 0) {
            return false;
        }
        batAmbushWindowTimer = 0;
        return true;
    }

    private double batSpecialDamageScale(boolean boosted) {
        return boosted ? 1.22 : 1.0;
    }

    private void handleBatSpecialState() {
        if (type != BirdGame3.BirdType.BAT) {
            return;
        }

        if (batWingcutTimer > 0) {
            vx = batWingcutDirection * (batWingcutFromHang
                    ? (batWingcutUltimate ? 20.0 : 17.0)
                    : (batWingcutUltimate ? 22.0 : 19.0));
            if (batWingcutFromHang) {
                vy *= 0.12;
            } else {
                vy = Math.min(vy, batWingcutUltimate ? -3.0 : -2.0);
            }
            applyBatWingcutHits();
            if (SimRng.next() < 0.86) {
                game.particles.add(new Particle(
                        bodyCenterX() - batWingcutDirection * 26.0,
                        bodyCenterY() + 12.0,
                        -batWingcutDirection * (2.0 + SimRng.next() * 3.0),
                        0.4 + SimRng.next() * 1.6,
                        batWingcutUltimate ? Color.GOLD : Color.MEDIUMPURPLE.brighter()
                ));
            }
        }

        if (batMoonriseTimer > 0) {
            vx *= 0.92;
            vy = Math.min(vy, batMoonriseUltimate ? -18.0 : -15.5);
            applyBatMoonriseHits();
            if (!batMoonriseBurstResolved && batMoonriseTimer <= 4) {
                resolveBatMoonriseBurst();
            }
        }

        if (batSilentStallTimer > BAT_SILENT_STALL_FRAMES) {
            vx *= 0.84;
            vy = Math.min(vy, batSilentUltimate ? -15.0 : -13.0);
        } else if (batSilentStallTimer > 0) {
            vx *= 0.72;
            vy *= 0.18;
            if (batSilentStallTimer == 1) {
                batSilentDiveTimer = batSilentUltimate ? BAT_SILENT_DIVE_FRAMES + 4 : BAT_SILENT_DIVE_FRAMES;
                vy = batSilentUltimate ? 24.0 : (batSilentFromHang ? 23.0 : 20.0);
            }
        } else if (batSilentDiveTimer > 0) {
            vx *= 0.96;
            vy = Math.max(vy, batSilentUltimate ? 24.0 : (batSilentFromHang ? 23.0 : 20.0));
            applyBatSilentDiveHits();
        }

        if (batCathedralTimer > 0 && batCathedralPulseCooldown <= 0) {
            fireBatCathedralPulse();
        }
    }

    private void handleBatPostMoveSpecialState() {
        if (type != BirdGame3.BirdType.BAT) {
            return;
        }
        if (batWingcutFromHang && batWingcutTimer > 0 && batWingcutTimer <= 2) {
            Platform hangable = findBatHangablePlatform();
            if (hangable != null) {
                beginBatHang(hangable);
                batWingcutTimer = 0;
                return;
            }
        }
        if (batWingcutFromHang && batWingcutTimer > 0) {
            Platform hangable = findBatHangablePlatform();
            if (hangable != null) {
                double leftBound = hangable.x + 10;
                double rightBound = hangable.x + hangable.w - (80 * sizeMultiplier) - 10;
                boolean nearingEdge = batWingcutDirection > 0
                        ? x >= rightBound - 12.0 * sizeMultiplier
                        : x <= leftBound + 12.0 * sizeMultiplier;
                if (nearingEdge) {
                    beginBatHang(hangable);
                    batWingcutTimer = 0;
                    return;
                }
            }
        }
        if (((batWingcutTimer > 0 && !batWingcutFromHang) || batMoonriseTimer > 0) && vy < -1.0) {
            Platform hangable = findBatHangablePlatform();
            if (hangable != null) {
                beginBatHang(hangable);
                batWingcutTimer = 0;
                batMoonriseTimer = 0;
                return;
            }
        }
        if (batSilentDiveTimer > 0 && isOnGround()) {
            batSilentDiveTimer = 0;
            emitBatLandingBurst();
        }
    }

    private void handleRavenSpecialState(boolean specialHeld) {
        if (type != BirdGame3.BirdType.RAVEN) {
            return;
        }

        if (ravenQuillCharging) {
            ravenQuillChargeFrames++;
            vx *= isOnGround() ? 0.84 : 0.94;
            if (!specialHeld || ravenQuillChargeFrames >= RAVEN_QUILL_CHARGE_FAN_FRAMES + 18) {
                fireRavenBlackQuillVolley(ravenQuillChargeFrames >= RAVEN_QUILL_CHARGE_FAN_FRAMES, ravenQuillChargeUltimate);
            }
        }

        if (ravenUltimateWindupTimer > 0) {
            vx *= 0.58;
            vy *= 0.42;
            if ((ravenUltimateWindupTimer & 3) == 0) {
                emitRavenUltimatePortalFeathers(4, false);
            }
            if (ravenUltimateWindupTimer == 1) {
                resolveRavenUnkindnessMainStrike();
            }
        }

        if (ravenSideTimer > 0) {
            vx = ravenSideDirection * (ravenSideUltimate ? 11.0 : 8.0);
            vy *= 0.36;
            if (!ravenSideResolved) {
                applyRavenShadowWarpHits();
                ravenSideResolved = true;
            }
            if ((ravenSideTimer & 1) == 0) {
                emitRavenBurst(bodyCenterX() - ravenSideDirection * 18.0 * sizeMultiplier,
                        bodyCenterY() + 4.0 * sizeMultiplier,
                        ravenSideUltimate ? 6 : 4,
                        ravenSideUltimate ? Color.GOLD : ravenShadowColor(false));
            }
        }

        if (ravenLiftTimer > 0) {
            vx *= 0.86;
            vy = Math.min(vy, ravenLiftUltimate ? -18.5 : -15.5);
            if (!ravenLiftSnapped) {
                RavenNode snapNode = nearestRavenSnapNode();
                if (snapNode != null) {
                    double oldX = bodyCenterX();
                    double oldY = bodyCenterY();
                    consumeRavenNode(snapNode);
                    x = clampRavenWarpX(snapNode.x() - 40.0 * sizeMultiplier);
                    y = clampRavenWarpY(snapNode.y() - 72.0 * sizeMultiplier);
                    vy = Math.min(vy, ravenLiftUltimate ? -24.0 : -20.5);
                    ravenLiftSnapped = true;
                    emitRavenBurst(oldX, oldY, ravenLiftUltimate ? 30 : 20, ravenShadowColor(false));
                    emitRavenBurst(bodyCenterX(), bodyCenterY(), ravenLiftUltimate ? 36 : 24,
                            ravenLiftUltimate ? Color.GOLD : ravenAccentColor());
                }
            }
            applyRavenLiftHits();
            if ((ravenLiftTimer & 1) == 0) {
                emitRavenBurst(bodyCenterX(), bodyBottomY() - 6.0 * sizeMultiplier,
                        ravenLiftUltimate ? 7 : 4,
                        ravenLiftUltimate ? Color.GOLD : ravenAccentColor());
            }
        }
    }

    private void handleRavenPostMoveSpecialState() {
        if (type != BirdGame3.BirdType.RAVEN) {
            return;
        }
        handleRavenQuills();
        handleRavenGroundPortents();
        handleRavenDecoy();
        handleRavenUltimatePortals();
        handleRavenUltimateRoutes();
        handleRavenUltimateFlock();
    }

    private void handleRavenQuills() {
        for (Iterator<RavenQuill> it = ravenQuills.iterator(); it.hasNext(); ) {
            RavenQuill quill = it.next();
            double prevX = quill.x;
            double prevY = quill.y;
            quill.x += quill.vx;
            quill.y += quill.vy;
            quill.lifeFrames--;

            boolean consumed = false;
            for (Bird other : game.players) {
                if (!canDamageTarget(other)) continue;
                if (Math.abs(other.bodyCenterX() - quill.x) > 18.0 * sizeMultiplier + other.combatHalfWidth()) continue;
                if (Math.abs(other.bodyCenterY() - quill.y) > 18.0 * sizeMultiplier + other.combatHalfHeight()) continue;
                int dealt = applyTrackedSpecialDamage(other, quill.ultimate ? 7 : 5);
                if (dealt > 0) {
                    double dir = Math.signum(quill.vx == 0.0 ? facingDirection() : quill.vx);
                    other.vx += dir * (quill.ultimate ? 7.0 : 5.0);
                    other.vy -= quill.ultimate ? 4.6 : 3.2;
                    applyRavenPortent(other, quill.ultimate);
                    game.playHitSound(dealt);
                    emitRavenBurst(quill.x, quill.y, quill.ultimate ? 18 : 12,
                            quill.ultimate ? Color.GOLD : ravenAccentColor());
                }
                consumed = true;
                break;
            }
            if (consumed) {
                it.remove();
                continue;
            }

            Double surfaceY = ravenQuillImpactSurfaceY(prevX, prevY, quill.x, quill.y);
            if (surfaceY != null) {
                addRavenGroundPortent(quill.x, surfaceY, quill.ultimate);
                emitRavenBurst(quill.x, surfaceY - 10.0 * sizeMultiplier, quill.ultimate ? 18 : 12,
                        quill.ultimate ? Color.GOLD : ravenAccentColor());
                it.remove();
                continue;
            }
            if (quill.lifeFrames <= 0
                    || quill.x < -40.0
                    || quill.x > BirdGame3.WORLD_WIDTH + 40.0
                    || quill.y < -80.0
                    || quill.y > BirdGame3.GROUND_Y + 80.0) {
                it.remove();
            }
        }
    }

    private Double ravenQuillImpactSurfaceY(double prevX, double prevY, double nextX, double nextY) {
        if (prevY <= BirdGame3.GROUND_Y && nextY >= BirdGame3.GROUND_Y) {
            return (double) BirdGame3.GROUND_Y;
        }
        for (Platform platform : game.platforms) {
            boolean isCaveCeiling = game.selectedMap == MapType.CAVE
                    && platform.y <= 1 && platform.h >= 60 && platform.w >= BirdGame3.WORLD_WIDTH - 10;
            if (isCaveCeiling || platform.w <= 0 || platform.h <= 0) continue;
            if (nextX < platform.x - 6.0 || nextX > platform.x + platform.w + 6.0) continue;
            if (prevY <= platform.y && nextY >= platform.y) {
                return platform.y;
            }
        }
        return null;
    }

    private void handleRavenGroundPortents() {
        for (Iterator<RavenPortent> it = ravenGroundPortents.iterator(); it.hasNext(); ) {
            RavenPortent portent = it.next();
            portent.ageFrames++;
            portent.lifeFrames--;
            if (portent.lifeFrames <= 0) {
                it.remove();
            } else if ((portent.ageFrames & 15) == 0) {
                emitRavenBurst(portent.x, portent.y - 10.0 * sizeMultiplier,
                        portent.ultimate ? 4 : 3,
                        portent.ultimate ? Color.GOLD : ravenAccentColor());
            }
        }
    }

    private void handleRavenDecoy() {
        if (ravenDecoy == null) {
            return;
        }
        ravenDecoy.ageFrames++;
        ravenDecoy.lifeFrames--;
        if (ravenDecoy.lifeFrames <= 0) {
            ravenDecoy = null;
            return;
        }
        for (Bird other : game.players) {
            if (!canDamageTarget(other)) continue;
            if (other.playerIndex < 0 || other.playerIndex >= ravenDecoy.hit.length) continue;
            if (ravenDecoy.hit[other.playerIndex]) continue;
            double dx = other.bodyCenterX() - ravenDecoy.x;
            double dy = other.bodyCenterY() - ravenDecoy.y;
            if (Math.abs(dx) > 54.0 * sizeMultiplier + other.combatHalfWidth()) continue;
            if (Math.abs(dy) > 68.0 * sizeMultiplier + other.combatHalfHeight()) continue;
            int dealt = applyTrackedSpecialDamage(other, ravenDecoy.ultimate ? 12 : 8);
            if (dealt > 0) {
                other.applyStun(ravenDecoy.ultimate ? 20 : 14);
                other.vx += Math.signum(dx == 0.0 ? facingDirection() : dx) * (ravenDecoy.ultimate ? 12.0 : 8.5);
                other.vy -= ravenDecoy.ultimate ? 8.0 : 5.8;
                applyRavenPortent(other, ravenDecoy.ultimate);
                game.playHitSound(dealt);
            }
            ravenDecoy.hit[other.playerIndex] = true;
            emitRavenBurst(ravenDecoy.x, ravenDecoy.y, ravenDecoy.ultimate ? 44 : 28,
                    ravenDecoy.ultimate ? Color.GOLD : ravenAccentColor());
            ravenDecoy = null;
            return;
        }
    }

    private void handleRavenUltimatePortals() {
        for (Iterator<RavenUltimatePortal> it = ravenUltimatePortals.iterator(); it.hasNext(); ) {
            RavenUltimatePortal portal = it.next();
            portal.ageFrames++;
            portal.lifeFrames--;
            if (portal.lifeFrames <= 0) {
                it.remove();
                continue;
            }
            if ((portal.ageFrames & 5) == 0) {
                double angle = portal.angleOffset + portal.ageFrames * 0.21;
                double radius = portal.radius * (0.55 + SimRng.next() * 0.45) * sizeMultiplier;
                game.particles.add(new Particle(
                        portal.x + Math.cos(angle) * radius,
                        portal.y + Math.sin(angle) * radius * 0.62,
                        Math.cos(angle + Math.PI * 0.5) * (1.6 + SimRng.next() * 2.4),
                        Math.sin(angle + Math.PI * 0.5) * (1.0 + SimRng.next() * 2.0) - 1.2,
                        (portal.ageFrames % 2 == 0 ? Color.web("#B388FF") : Color.web("#CFD8DC"))
                                .deriveColor(0, 1, 1, 0.72)
                ));
            }
        }
    }

    private void handleRavenUltimateRoutes() {
        for (Iterator<RavenUltimateRoute> it = ravenUltimateRoutes.iterator(); it.hasNext(); ) {
            RavenUltimateRoute route = it.next();
            route.ageFrames++;
            route.lifeFrames--;
            if (route.lifeFrames <= 0) {
                it.remove();
                continue;
            }
            if ((route.ageFrames & 3) == 0) {
                double t = route.ageFrames / (double) Math.max(1, RAVEN_ULTIMATE_ROUTE_LIFE_FRAMES);
                emitRavenBurst(
                        route.startX + (route.endX - route.startX) * t,
                        route.startY + (route.endY - route.startY) * t,
                        5,
                        Color.GOLD
                );
            }
        }
    }

    private void handleRavenUltimateFlock() {
        if (ravenUltimateFlockTimer == 1 && !ravenUltimateFlockSpawned) {
            spawnRavenUltimateVoidFlock();
        }
    }

