                double launchDir = Math.signum(other.bodyCenterX() - startX);
                if (launchDir == 0.0) launchDir = facingDirection();
                other.vx += launchDir * (ultimate ? 13.0 : 9.0);
                other.vy -= ultimate ? 8.5 : 6.0;
