    private double applyScaledDamageTo(Bird target, double scaledDamage) {
        if (target == null || scaledDamage <= 0 || target.health <= 0) return 0;
        scaledDamage = target.adjustDamageForPenguinSnowFort(this, scaledDamage);
        double dealtDamage = target.receiveScaledDamage(scaledDamage, this);
        if (dealtDamage > 0) {
            if (game.usesSmashCombatRules()) {
                target.registerSmashHit(this, dealtDamage);
            }
            gainUltimate(dealtDamage * ULTIMATE_GAIN_DEALT);
            target.gainUltimate(dealtDamage * ULTIMATE_GAIN_TAKEN);
            game.recordTrainingHit(this, target, dealtDamage);
        }
        return dealtDamage;
    }

    private double adjustDamageForPenguinSnowFort(Bird attacker, double scaledDamage) {
        return PenguinSpecials.adjustDamageForSnowFort(this, attacker, scaledDamage);
    }

    double applyUnshieldedDamageTo(Bird target, double rawDamage) {
        return applyScaledDamageTo(target, scaledDamageAgainst(target, rawDamage));
    }

    double applyDamageTo(Bird target, double rawDamage) {
        if (target == null || rawDamage <= 0 || target.health <= 0) return 0;
        double scaledDamage = scaledDamageAgainst(target, rawDamage);
        if (target.tryRazorbillCounter(this, scaledDamage)) {
            return 0;
        }
        if (target.tryShoebillStatueCounter(this, scaledDamage)) {
            return 0;
        }
        if (target.tryGooseNestCounter(this, scaledDamage)) {
            return 0;
        }
        ShieldHitResult shieldHit = target.resolveShieldHit(this, scaledDamage, 0.0);
        if (shieldHit.blocked()) {
            return 0;
        }
        scaledDamage += target.consumeHeisenBrittleBonusFrom(this);
        return applyScaledDamageTo(target, scaledDamage);
    }

    int applyTrackedSpecialDamage(Bird target, int rawDamage) {
        if (target == null || rawDamage <= 0) {
            return 0;
        }
        double oldHealth = target.health;
        int dealt = (int) applyDamageTo(target, rawDamage);
        if (dealt <= 0) {
            return 0;
        }
        game.damageDealt[playerIndex] += dealt;
        game.recordSpecialImpact(playerIndex, dealt, true);
        confirmSpecialHit(dealt, specialHitConfirmAccent());
        String impactMoveName = game.lastTelemetryMoveName(playerIndex, type.name + " Special");
        boolean isKill = target.health <= 0 && oldHealth > 0;
        game.emitCombatImpact(this, target, target.bodyCenterX(), target.bodyCenterY(),
                target.vx, target.vy, dealt, isKill, impactMoveName);
        if (isKill) {
            game.eliminations[playerIndex]++;
            game.recordMoveKo(this, target, impactMoveName);
        }
        return dealt;
    }

    void confirmSpecialHit(int dealt, Color color) {
        if (dealt <= 0) {
            return;
        }
        specialHitConfirmDamage = specialHitConfirmTimer > 0
                ? Math.min(999, specialHitConfirmDamage + dealt)
                : dealt;
        specialHitConfirmTimer = SPECIAL_HIT_CONFIRM_FRAMES;
        specialHitConfirmColor = color == null ? Color.WHITE : color;
    }

    private Color specialHitConfirmAccent() {
        if (type == BirdGame3.BirdType.TITMOUSE) {
            return Color.web("#CFD8DC");
        }
        if (type == BirdGame3.BirdType.HEISENBIRD) {
            return Color.web("#81D4FA");
        }
        if (type == BirdGame3.BirdType.OPIUMBIRD) {
            return Color.web("#CE93D8");
        }
        return Color.web("#FFF176");
    }

